create temporary view dwd_derived_scenario_${grass_region_without_quote} as
select
    user_id
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,case when location >= 250 then 250 else location end as location
    ,case when source1_location >= 250 then 250 else source1_location end as source1_location
    ,case when source2_location >= 250 then 250 else source2_location end as source2_location

    ,operation
    ,operation_cnt
    ,is_back
    ,place_order_gmv
    ,window_day

     -- concat(A,B) if A or B is null ,the result is null
    ,case when reporting_business_line = 'Homepage' then concat('dpm business line ', reporting_business_line) else null end as reporting_business_line
    ,case when reporting_business_line = 'Homepage' then concat('dpm module ', reporting_module, ' business line ', reporting_business_line) else null end as reporting_module
    ,algo_tag
    ,concat('Page ', split(if(feature_detail = '', null, feature_detail), '-')[0]) as mapped_page_type

    ,case when source1_reporting_business_line = 'Homepage' then concat('dpm business line ', source1_reporting_business_line) else null end as source1_reporting_business_line
    ,case when source1_reporting_business_line = 'Homepage' then concat('dpm module ', source1_reporting_module, ' business line ', source1_reporting_business_line) else null end as source1_reporting_module
    ,source1_algo_tag
    ,concat('Page ', split(if(source1_feature_detail = '', null, source1_feature_detail), '-')[0]) as source1_mapped_page_type

    ,case when source2_reporting_business_line = 'Homepage' then concat('dpm business line ', source2_reporting_business_line) else null end as source2_reporting_business_line
    ,case when source2_reporting_business_line = 'Homepage' then concat('dpm module ', source2_reporting_module, ' business line ', source2_reporting_business_line) else null end as source2_reporting_module
    ,source2_algo_tag
    ,concat('Page ', split(if(source2_feature_detail = '', null, source2_feature_detail), '-')[0]) as source2_mapped_page_type

from srdi_mart.dwd_sr_data_warehouse_platform
where
    grass_region in (${grass_region})
    and local_date = ${local_date}
    and operation in ('impression', 'click', 'ppv', 'cart', 'order', 'omni_impression', 'omni_click')
    and feature_detail not in ('bottom_bar-tab', 'phone_notifications-push_notification','chat-chat_conversation','home-home_circle','me-self_design_button',
                                'home-skinny_banner', 'home-shopee_wallet-button','product-image_card','product-variation_image-image')
;

--sql_divide_splitter--
create temporary view concat_data_raw_${grass_region_without_quote} as
select
     *
    ,concat_ws(',', reporting_business_line, reporting_module, algo_tag, mapped_page_type) AS scenario_tags_str
    ,concat_ws(',', source1_reporting_business_line, source1_reporting_module, source1_algo_tag, source1_mapped_page_type) AS source1_scenario_tags_str
    ,concat_ws(',', source2_reporting_business_line, source2_reporting_module, source2_algo_tag, source2_mapped_page_type) AS source2_scenario_tags_str
from
    dwd_derived_scenario_${grass_region_without_quote}
;

--sql_divide_splitter--
create temporary view concat_data_${grass_region_without_quote} as
select
     *
     -- algo_tag is already contain ',',so  concat_ws then  split to align with current code
    ,coalesce(split(if(scenario_tags_str = '', null, scenario_tags_str), ','), array()) AS scenario_tags
    ,coalesce(split(if(source1_scenario_tags_str = '', null, source1_scenario_tags_str), ','), array()) AS source1_scenario_tags
    ,coalesce(split(if(source2_scenario_tags_str = '', null, source2_scenario_tags_str), ','), array()) AS source2_scenario_tags
from concat_data_raw_${grass_region_without_quote}
;

--sql_divide_splitter--
create temporary view user_location_base_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,scenario_tags
    ,source1_scenario_tags
    ,source2_scenario_tags
    ,location
    ,source1_location
    ,source2_location

    ,sum(case when operation = 'impression' then operation_cnt else 0 end)          as imp_cnt
    ,sum(case when operation = 'click' then operation_cnt else 0 end)               as click_cnt
    ,sum(case when operation = 'omni_impression' then operation_cnt else 0 end)     as omni_imp_cnt
    ,sum(case when operation = 'omni_click' then operation_cnt else 0 end)          as omni_click_cnt
    ,sum(case when operation = 'cart' then operation_cnt else 0 end)                as cart_cnt
    ,sum(case when operation = 'ppv' then operation_cnt else 0 end)                                 as ppv_cnt
    ,sum(case when operation = 'ppv' and is_back is not true then operation_cnt else 0 end)         as ppv_cnt_exclude_isback
    ,sum(case when operation = 'order' then operation_cnt else 0 end)               as order_cnt
    ,sum(case when operation = 'order' then place_order_gmv else 0 end)             as gmv
    ,sum(if(operation='order' and window_day=1, operation_cnt, 0))                  as atc_same_day_order_cnt
    ,sum(if(operation='order' and window_day between 1 and 4, operation_cnt, 0))    as atc_within_3day_order_cnt
    ,sum(if(operation='order' and window_day=1, place_order_gmv, 0))                as atc_same_day_gmv
    ,sum(if(operation='order' and window_day between 1 and 4, place_order_gmv, 0))  as atc_within_3day_gmv
from
    concat_data_${grass_region_without_quote}
where
    size(scenario_tags) > 1
    or size(source1_scenario_tags) > 1
    or size(source2_scenario_tags) > 1
group by
    1, 2, 3, 4, 5, 6, 7, 8
;

