CREATE TEMPORARY VIEW metrics_agg_${grass_region_without_quote} AS
SELECT is_ads
       ,location
       ,scenario_tag
       ,count(distinct case when imp_cnt > 0 then user_id else null end) as imp_uu
       ,count(distinct case when click_cnt > 0 then user_id else null end) as click_uu
       ,count(distinct case when omni_imp_cnt > 0 then user_id else null end) as omni_imp_uu
       ,count(distinct case when omni_click_cnt > 0 then user_id else null end) as omni_click_uu
       ,count(distinct case when ppv_cnt_exclude_isback > 0 then user_id else null end) as ppv_exclude_isback_uu
       ,count(distinct case when cart_cnt > 0 then user_id else null end) as atc_uu
       ,count(distinct case when order_cnt > 0 then user_id else null end) as order_uu
       ,sum(case when imp_cnt > 0 then imp_cnt else 0 end) as imp_cnt
       ,sum(case when click_cnt > 0 then click_cnt else 0 end) as click_cnt
       ,sum(case when omni_imp_cnt > 0 then omni_imp_cnt else 0 end) as omni_imp_cnt
       ,sum(case when omni_click_cnt > 0 then omni_click_cnt else 0 end) as omni_click_cnt
       ,sum(case when ppv_cnt > 0 then ppv_cnt else 0 end) as ppv_cnt
       ,sum(case when ppv_cnt_exclude_isback > 0 then ppv_cnt_exclude_isback else 0 end) as ppv_cnt_exclude_isback
       ,sum(case when cart_cnt > 0 then cart_cnt else 0 end) as cart_cnt
       ,sum(case when order_cnt > 0 then order_cnt else 0 end) as order_cnt
       ,sum(case when gmv > 0 then gmv else 0 end) as gmv
       ,sum(case when atc_same_day_order_cnt > 0 then atc_same_day_order_cnt else 0 end) as atc_same_day_order_cnt
       ,sum(case when atc_within_3day_order_cnt > 0 then atc_within_3day_order_cnt else 0 end) as atc_within_3day_order_cnt
       ,sum(case when atc_same_day_gmv > 0 then atc_same_day_gmv else 0 end) as atc_same_day_gmv
       ,sum(case when atc_within_3day_gmv > 0 then atc_within_3day_gmv else 0 end) as atc_within_3day_gmv
FROM base_table_exploded_${grass_region_without_quote}
WHERE LENGTH(scenario_tag) > 0
GROUP BY GROUPING SETS (
   (is_ads, location, scenario_tag),
   (location, scenario_tag)
);

